Question: Write a function void evenSort(int arr[], int size) that puts all even numbers first, and then odd numbers.

Code:
#include <iostream>
using namespace std;

void evenSort(int arr[], int size) {
    if (arr == nullptr || size <= 0) {
        return;
    }

    // Lomuto partition scheme variation
    // Place evens at the beginning
    int j = -1; // Last index of even numbers found so far
    for (int i = 0; i < size; i++) {
        if (arr[i] % 2 == 0) {
            j++;
            int temp = arr[i];
            arr[i] = arr[j];
            arr[j] = temp;
        }
    }
}

int main() {
    int arr[] = {1, 2, 3, 4, 5, 6, 7, 8};
    int size = sizeof(arr) / sizeof(arr[0]);

    evenSort(arr, size);

    cout << "Array after segregation: ";
    for (int i = 0; i < size; i++) {
        cout << arr[i] << " ";
    }
    cout << endl;

    return 0;
}

Question: Write a function int searchData(int arr[], int size, int key) that performs binary search to find the key in the sorted array. Return the index if found, -1 otherwise.

Code:
#include <iostream>
using namespace std;

int searchData(int arr[], int size, int key) {
    if (arr == nullptr || size <= 0) {
        return -1;
    }

    int start = 0;
    int end = size - 1;

    while (start <= end) {
        // Prevent integer overflow for large indices
        int mid = start + (end - start) / 2;

        if (arr[mid] == key) {
            return mid;
        } else if (key < arr[mid]) {
            end = mid - 1;
        } else {
            start = mid + 1;
        }
    }
    return -1;
}

int main() {
    int arr[] = {-1, 0, 1, 2, 10, 34, 40, 44, 51, 99};
    int size = sizeof(arr) / sizeof(arr[0]);

    int key1 = 40;
    int index1 = searchData(arr, size, key1);
    if (index1 != -1) cout << key1 << " found at index " << index1 << endl;
    else cout << key1 << " not found" << endl;

    int key2 = 999;
    int index2 = searchData(arr, size, key2);
    if (index2 != -1) cout << key2 << " found at index " << index2 << endl;
    else cout << key2 << " not found" << endl;

    return 0;
}

