    return 0;
}

Question: Write a function void lookupName(string target, string names[], string numbers[], int size) that finds and displays the phone number for the target name.

Code:
#include <iostream>
#include <string>
using namespace std;

void lookupName(const string& target, const string names[], const string numbers[], int size) {
    if (names == nullptr || numbers == nullptr || size < 0) {
        cout << "Invalid input." << endl;
        return;
    }

    bool found = false;
    for (int i = 0; i < size; i++) {
        if (names[i] == target) {
            cout << "Phone number: " << numbers[i] << endl;
            found = true;
            break; // Stop after finding the first match
        }
    }

    if (!found) {
        cout << "Name not found." << endl;
    }
