        os << c.imaginary << "i";
    } else {
        os << c.real;
        if (c.imaginary > 0) {
            os << " + " << c.imaginary << "i";
        } else {
            os << " - " << std::abs(c.imaginary) << "i";
        }
    }
    return os;
}

