#include <string>

class Base {
public:
    Base() {
        std::cout << "Base Constructor" << std::endl;
    }
    // Base destructor is NOT virtual, which is the root cause of the problem.
    ~Base() {
        std::cout << "Base Destructor" << std::endl;
    }
};

class Derived : public Base {
