    }

private:
    int privateVar;
    void privateMethod() {
        std::cout << "Private method called. privateVar = " << privateVar << std::endl;
    }

protected:
    int protectedVar;
    void protectedMethod() {
        std::cout << "Protected method called. protectedVar = " << protectedVar << std::endl;
    }

public:
    MyClass() : publicVar(10), privateVar(20), protectedVar(30) {}
};

