    Point p2(5, 5);
    Point& ref_p2 = ++p2; // p2 becomes (6,6). ref_p2 points to static temp_static_point, which is (6,6)
    ss << "After ++p2, p2: " << p2 << std::endl; // p2 is (6,6)
    ss << "Reference ref_p2: " << ref_p2 << std::endl; // ref_p2 is (6,6)
