// BaseClass definition
class BaseClass {
private:
    int privateMember;
protected:
    int protectedMember;
public:
    int publicMember;

    BaseClass() : privateMember(10), protectedMember(20), publicMember(30) {}

    void displayBaseMembers() {
        std::cout << "BaseClass members (from BaseClass itself):" << std::endl;
        std::cout << "  Private: " << privateMember << std::endl;
        std::cout << "  Protected: " << protectedMember << std::endl;
        std::cout << "  Public: " << publicMember << std::endl;
    }

    int getPrivateMember() const { return privateMember; }
};

// DerivedClass definition
class DerivedClass : public BaseClass {
public:
    void accessBaseMembers() {
        std::cout << "\nDerivedClass attempting to access BaseClass members:" << std::endl;
        std::cout << "  Accessing publicMember (allowed): " << publicMember << std::endl;
        std::cout << "  Accessing protectedMember (allowed): " << protectedMember << std::endl;

        // Semantic Error: Attempting to access a private member directly from a derived class.
        // This will result in a compile-time error.
        std::cout << "  Accessing privateMember (NOT allowed directly from derived): " << privateMember << std::endl; // ERROR LINE
    }
};

int main() {
    std::cout << "Demonstrating C++ Access Specifiers (Semantic Error Example)\n" << std::endl;

    BaseClass baseObj;
    baseObj.displayBaseMembers();

    DerivedClass derivedObj;
    derivedObj.accessBaseMembers(); // This call will attempt the forbidden access, causing a compile error.

    std::cout << "\nFrom main() function:" << std::endl;
    std::cout << "  Accessing baseObj.publicMember (allowed): " << baseObj.publicMember << std::endl;
    std::cout << "  Attempting to access baseObj.protectedMember directly: NOT PERMITTED (semantic error if uncommented)" << std::endl;
    std::cout << "  Attempting to access baseObj.privateMember directly: NOT PERMITTED (semantic error if uncommented)" << std::endl;
    std::cout << "  Accessing baseObj.privateMember via public getter (allowed): " << baseObj.getPrivateMember() << std::endl;

    return 0;
}

Question: Design a `SecretAgent` class where the agent's `codename` is public, `trueIdentity` is private, and `missionBriefing` is protected. Show how these access levels restrict or permit access from outside and from a derived class `Handler`.

Code:
#include <iostream>
#include <string>

class SecretAgent {
public:
    std::string codename;

    SecretAgent(std::string code, std::string identity, std::string briefing)
        : codename(code), trueIdentity(identity), missionBriefing(briefing) {}

    void displayCodename() const {
        std::cout << "Agent Codename: " << codename << std::endl;
    }

private:
    std::string trueIdentity;

protected:
    std::string missionBriefing;

    void revealMissionBriefingInternal() const {
        std::cout << "Internal Briefing Access: " << missionBriefing << std::endl;
    }
};

class Handler : public SecretAgent {
public:
    Handler(std::string code, std::string identity, std::string briefing, std::string handlerID)
        : SecretAgent(code, identity, briefing), handlerID_(handlerID) {}

    void accessAgentInfo() const {
        std::cout << "\n--- Handler Accessing Agent Info ---" << std::endl;
        // Access public member (permitted)
        std::cout << "Handler can see Codename: " << codename << std::endl;

        // Access protected member (permitted for derived class)
        std::cout << "Handler can access Mission Briefing: " << missionBriefing << std::endl;
        revealMissionBriefingInternal(); // Can call protected method

        // Attempt to access private member (not permitted - this will cause a semantic error)
        std::cout << "Handler trying to access True Identity: " << trueIdentity << std::endl;
    }

private:
    std::string handlerID_;
};

int main() {
    SecretAgent agent1("Phoenix", "John Doe", "Infiltrate organization X.");
    Handler handler1("Viper", "Jane Smith", "Extract target Y.", "Alpha7");

    std::cout << "--- Outside Access (from main) ---" << std::endl;
    // Access public member (permitted)
    agent1.displayCodename();
    std::cout << "Main can see Agent Codename: " << agent1.codename << std::endl;

    // Attempt to access private member (not permitted - this will cause a semantic error)
    std::cout << "Main trying to access True Identity: " << agent1.trueIdentity << std::endl;

    // Attempt to access protected member (not permitted from outside the class or derived classes - this will cause a semantic error)
    std::cout << "Main trying to access Mission Briefing: " << agent1.missionBriefing << std::endl;

    handler1.accessAgentInfo();

    return 0;
}

