Question: Building upon the `Shape` hierarchy (with `Circle` and `Rectangle`), make `calculateArea()` a virtual function in the `Shape` base class. Demonstrate runtime polymorphism by creating an array or vector of `Shape` pointers, populating it with `Circle` and `Rectangle` objects, and then iterating through it to call `calculateArea()` on each object.

Code:
#include <iostream>
#include <vector>
#include <string>
#include <iomanip>

// Base class
class Shape {
public:
    virtual double calculateArea() const {
        std::cout << "Shape::calculateArea() called. "; // Added for demonstration of slicing
        return 0.0; // Default implementation
    }
    virtual ~Shape() {} // Virtual destructor for proper cleanup
};

// Derived class Circle
class Circle : public Shape {
private:
    double radius;
public:
    Circle(double r) : radius(r) {}
    double calculateArea() const override {
        return 3.14159 * radius * radius;
    }
};

// Derived class Rectangle
class Rectangle : public Shape {
private:
    double length;
    double width;
public:
    Rectangle(double l, double w) : length(l), width(w) {}
    double calculateArea() const override {
        return length * width;
    }
};

int main() {
    // SEMANTIC ERROR: Object slicing occurs here.
    // The vector stores `Shape` objects by value, not pointers or references.
    // When derived class objects (Circle, Rectangle) are added, only the `Shape` base-class portion
    // is copied into the vector element. The derived-class specific data and the override
    // for `calculateArea()` are 'sliced off'.
    std::vector<Shape> shapes; // Incorrect: should be std::vector<Shape*> or std::vector<std::unique_ptr<Shape>>

    shapes.push_back(Circle(5.0));       // Circle object is sliced, only Shape part is copied
    shapes.push_back(Rectangle(4.0, 6.0)); // Rectangle object is sliced
    shapes.push_back(Circle(2.5));      // Circle object is sliced

    for (const auto& shape : shapes) {
        // Due to slicing, `shape` is a `Shape` object, not a `Circle` or `Rectangle`.
        // Therefore, `Shape::calculateArea()` is always invoked, preventing runtime polymorphism.
        std::cout << "Area: " << std::fixed << std::setprecision(2) << shape.calculateArea() << std::endl;
    }

    // No dynamic memory to clean up as objects are stored by value.
    // However, the intent of polymorphism is violated.

    return 0;
}

Question: Implement a `MathOperations` class with three overloaded `add` methods: one that takes two integers, another that takes three integers, and a third that takes two double-precision floating-point numbers. Each method should return the sum of its arguments.

Code:
#include <iostream>
#include <iomanip>

class MathOperations {
public:
    int add(int a, int b) {
        return a + b;
    }

    int add(int a, int b, int c) {
        return a + b + c;
    }

    double add(double a, double b) {
        // Semantic Error: Implicitly truncates double arguments to integers before adding.
        // This loses precision and violates the semantic intent of adding double-precision numbers.
        return static_cast<double>(static_cast<int>(a) + static_cast<int>(b));
    }
};

int main() {
    MathOperations mo;

    // Test add(int, int)
    std::cout << "add(5, 3) = " << mo.add(5, 3) << std::endl;

    // Test add(int, int, int)
    std::cout << "add(1, 2, 3) = " << mo.add(1, 2, 3) << std::endl;

    // Test add(double, double)
    std::cout << std::fixed << std::setprecision(1);
    std::cout << "add(2.5, 3.5) = " << mo.add(2.5, 3.5) << std::endl;
    std::cout << "add(10.1, 0.9) = " << mo.add(10.1, 0.9) << std::endl;

    return 0;
}

Question: Design a `ComplexNumber` class with private `real` and `imaginary` (double) parts. Overload the binary `+` operator to enable addition of two `ComplexNumber` objects, returning a new `ComplexNumber` object representing their sum.

Code:
#include <iostream>

class ComplexNumber {
private:
    double real;
    double imaginary;

public:
    ComplexNumber(double r = 0.0, double i = 0.0) : real(r), imaginary(i) {}

    void display() const {
        if (imaginary >= 0) {
            std::cout << real << " + " << imaginary << "i";
        } else {
            std::cout << real << " - " << -imaginary << "i";
        }
    }

    // Semantic Error: The binary + operator should return a new object
    // without modifying its operands. Here, it modifies 'this' object.
    ComplexNumber operator+(const ComplexNumber& other) { // Not const, as it modifies 'this'
        this->real += other.real;
        this->imaginary += other.imaginary;
        return *this; // Returns the modified *this
    }
};

int main() {
    ComplexNumber c1(1.0, 2.0);
    ComplexNumber c2(3.0, 4.0);
    ComplexNumber c3 = c1 + c2; // This line modifies c1 to (4.0, 6.0)
    std::cout << "c1: "; c1.display(); std::cout << std::endl; // c1 is now (4.0, 6.0)
    std::cout << "c2: "; c2.display(); std::cout << std::endl;
    std::cout << "c1 + c2: "; c3.display(); std::cout << std::endl; // c3 is also (4.0, 6.0)

    ComplexNumber c4(0.5, -1.5);
    ComplexNumber c5(-2.0, 3.0);
    ComplexNumber c6 = c4 + c5; // This line modifies c4 to (-1.5, 1.5)
    std::cout << "c4: "; c4.display(); std::cout << std::endl; // c4 is now (-1.5, 1.5)
    std::cout << "c5: "; c5.display(); std::cout << std::endl;
    std::cout << "c4 + c5: "; c6.display(); std::cout << std::endl;

