#include <iostream>
#include <numeric> // For std::gcd in C++17
#include <cmath>   // For std::abs

class Fraction {
private:
    int numerator;
    int denominator;

    // Helper function for GCD
    int calculateGCD(int a, int b) const {
        return std::gcd(a, b);
    }

    void simplify() {
        if (denominator == 0) return;
        if (numerator == 0) {
            denominator = 1;
            return;
        }
        int common_divisor = calculateGCD(std::abs(numerator), std::abs(denominator));
        numerator /= common_divisor;
        denominator /= common_divisor;

        // Ensure denominator is positive
        if (denominator < 0) {
            numerator = -numerator;
            denominator = -denominator;
        }
    }

public:
    Fraction(int num = 0, int den = 1) : numerator(num), denominator(den) {
        if (denominator == 0) {
            std::cerr << "Error: Denominator cannot be zero. Setting to 1." << std::endl;
            this->denominator = 1;
        }
        simplify();
    }

    void print() const {
