// Function to clean and normalize the string (ignore case and spaces)
std::string cleanString(const std::string& str) {
    std::string cleaned;
    for (char c : str) {
        if (!std::isspace(static_cast<unsigned char>(c))) {
            cleaned += std::tolower(static_cast<unsigned char>(c));
        }
    }
    return cleaned;
